/* ============================================
   WellStream Platform — Global Styles
   ============================================ */

:root {
  --primary-navy: #15295A;
  --accent-green: #6CC24A;
  --dark-gray: #3C424B;
  --bg-dark: #0D1B2A;
  --bg-card: #1B2838;
  --bg-card-hover: #223044;
  --text-primary: #E8EEF4;
  --text-secondary: #9FB3C8;
  --text-muted: #6B8299;
  --border-color: #2A3A4D;
  --accent-teal: #00B4D8;
  --accent-blue: #0077B6;
  --gradient-hero: linear-gradient(135deg, #0D1B2A 0%, #15295A 50%, #0D1B2A 100%);
  --shadow-sm: 0 2px 8px rgba(0,0,0,0.3);
  --shadow-md: 0 4px 20px rgba(0,0,0,0.4);
  --shadow-lg: 0 8px 40px rgba(0,0,0,0.5);
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  background: var(--bg-dark);
  color: var(--text-primary);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

a {
  color: inherit;
  text-decoration: none;
}

img {
  max-width: 100%;
  display: block;
}

.container {
  width: 100%;
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 24px;
}

/* ============================================
   Typography
   ============================================ */

h1, h2, h3, h4, h5, h6 {
  font-weight: 700;
  line-height: 1.2;
  color: var(--text-primary);
}

h1 { font-size: clamp(2rem, 5vw, 3.5rem); }
h2 { font-size: clamp(1.5rem, 3vw, 2.5rem); }
h3 { font-size: clamp(1.2rem, 2vw, 1.5rem); }

.section-label {
  font-size: 0.8rem;
  font-weight: 600;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--accent-green);
  margin-bottom: 12px;
}

.section-title {
  font-size: clamp(1.5rem, 3vw, 2.5rem);
  font-weight: 700;
  margin-bottom: 16px;
}

.section-desc {
  font-size: 1.05rem;
  color: var(--text-secondary);
  max-width: 700px;
  line-height: 1.7;
}

/* ============================================
   Buttons
   ============================================ */

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 12px 28px;
  font-size: 0.95rem;
  font-weight: 600;
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: var(--transition);
  border: none;
  white-space: nowrap;
}

.btn-primary {
  background: var(--accent-green);
  color: #fff;
}

.btn-primary:hover {
  background: #5aad3d;
  transform: translateY(-2px);
  box-shadow: 0 4px 16px rgba(108, 194, 74, 0.3);
}

.btn-secondary {
  background: transparent;
  color: var(--text-primary);
  border: 1.5px solid var(--border-color);
}

.btn-secondary:hover {
  border-color: var(--accent-green);
  color: var(--accent-green);
  transform: translateY(-2px);
}

.btn-outline {
  background: transparent;
  color: var(--accent-teal);
  border: 1.5px solid var(--accent-teal);
}

.btn-outline:hover {
  background: var(--accent-teal);
  color: #fff;
}

/* ============================================
   Header / Navigation
   ============================================ */

.header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background: rgba(13, 27, 42, 0.92);
  backdrop-filter: blur(16px);
  border-bottom: 1px solid var(--border-color);
  transition: var(--transition);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 68px;
}

.logo {
  font-size: 1.4rem;
  font-weight: 800;
  color: var(--text-primary);
  letter-spacing: -0.02em;
}

.logo span {
  color: var(--accent-green);
}

.nav {
  display: flex;
  align-items: center;
  gap: 32px;
}

.nav-link {
  font-size: 0.9rem;
  font-weight: 500;
  color: var(--text-secondary);
  transition: var(--transition);
  position: relative;
}

.nav-link:hover {
  color: var(--text-primary);
}

.nav-link.active {
  color: var(--accent-green);
}

.nav-dropdown {
  position: relative;
}

.nav-dropdown-toggle {
  display: flex;
  align-items: center;
  gap: 4px;
  cursor: pointer;
  font-size: 0.9rem;
  font-weight: 500;
  color: var(--text-secondary);
  transition: var(--transition);
  background: none;
  border: none;
}

.nav-dropdown-toggle:hover {
  color: var(--text-primary);
}

.nav-dropdown-menu {
  position: absolute;
  top: calc(100% + 8px);
  left: 50%;
  transform: translateX(-50%) translateY(-8px);
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 8px 0;
  min-width: 200px;
  opacity: 0;
  visibility: hidden;
  transition: var(--transition);
  box-shadow: var(--shadow-lg);
  z-index: 1001;
}

.nav-dropdown:hover .nav-dropdown-menu,
.nav-dropdown.open .nav-dropdown-menu {
  opacity: 1;
  visibility: visible;
  transform: translateX(-50%) translateY(0);
}

.nav-dropdown-item {
  display: block;
  padding: 10px 20px;
  font-size: 0.9rem;
  color: var(--text-secondary);
  transition: var(--transition);
  white-space: nowrap;
}

.nav-dropdown-item:hover {
  background: var(--bg-card-hover);
  color: var(--text-primary);
}

.nav-cta {
  padding: 10px 22px;
  font-size: 0.85rem;
}

.mobile-menu-btn {
  display: none;
  background: none;
  border: none;
  color: var(--text-primary);
  font-size: 1.5rem;
  cursor: pointer;
}

/* ============================================
   Hero Section
   ============================================ */

.hero {
  position: relative;
  min-height: 100vh;
  display: flex;
  align-items: center;
  background: var(--gradient-hero);
  overflow: hidden;
  padding-top: 68px;
}

.hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at 30% 50%, rgba(0, 119, 182, 0.12) 0%, transparent 60%),
              radial-gradient(ellipse at 70% 20%, rgba(108, 194, 74, 0.08) 0%, transparent 50%);
  pointer-events: none;
}

.hero-grid {
  position: absolute;
  inset: 0;
  background-image: 
    linear-gradient(rgba(42, 58, 77, 0.15) 1px, transparent 1px),
    linear-gradient(90deg, rgba(42, 58, 77, 0.15) 1px, transparent 1px);
  background-size: 60px 60px;
  opacity: 0.4;
  pointer-events: none;
}

.hero-content {
  position: relative;
  z-index: 2;
  max-width: 720px;
}

.hero-title {
  font-size: clamp(2.2rem, 5.5vw, 4rem);
  font-weight: 800;
  line-height: 1.1;
  margin-bottom: 24px;
  letter-spacing: -0.02em;
}

.hero-title .highlight {
  color: var(--accent-green);
}

.hero-subtitle {
  font-size: clamp(1rem, 2vw, 1.25rem);
  color: var(--text-secondary);
  margin-bottom: 40px;
  line-height: 1.7;
  max-width: 600px;
}

.hero-buttons {
  display: flex;
  gap: 16px;
  flex-wrap: wrap;
}

/* ============================================
   Section Base
   ============================================ */

.section {
  padding: 100px 0;
  position: relative;
}

.section-alt {
  background: var(--bg-card);
}

.section-header {
  margin-bottom: 60px;
}

/* ============================================
   Featured Product Banner
   ============================================ */

.featured-banner {
  background: linear-gradient(135deg, var(--primary-navy) 0%, var(--bg-card) 100%);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 40px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  flex-wrap: wrap;
  margin-top: -50px;
  position: relative;
  z-index: 3;
  box-shadow: var(--shadow-md);
}

.featured-banner-content h3 {
  font-size: 1.3rem;
  margin-bottom: 4px;
}

.featured-banner-content p {
  color: var(--text-secondary);
  font-size: 0.95rem;
}

.featured-banner-tag {
  display: inline-block;
  background: rgba(108, 194, 74, 0.15);
  color: var(--accent-green);
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  padding: 4px 12px;
  border-radius: 20px;
  margin-bottom: 8px;
}

/* ============================================
   Use Cases Grid
   ============================================ */

.usecases-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
  gap: 24px;
}

.usecase-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 32px;
  transition: var(--transition);
  cursor: pointer;
}

.usecase-card:hover {
  border-color: var(--accent-green);
  transform: translateY(-4px);
  box-shadow: var(--shadow-md);
}

.usecase-icon {
  width: 48px;
  height: 48px;
  background: rgba(108, 194, 74, 0.1);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 20px;
  color: var(--accent-green);
  font-size: 1.5rem;
}

.usecase-card h3 {
  font-size: 1.1rem;
  margin-bottom: 10px;
}

.usecase-card p {
  font-size: 0.9rem;
  color: var(--text-secondary);
  line-height: 1.6;
}

/* ============================================
   Industry Tabs
   ============================================ */

.industry-tabs {
  margin-top: 40px;
}

.tabs-nav {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  margin-bottom: 32px;
  border-bottom: 1px solid var(--border-color);
  padding-bottom: 8px;
}

.tab-btn {
  padding: 10px 20px;
  font-size: 0.9rem;
  font-weight: 500;
  color: var(--text-muted);
  background: none;
  border: none;
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: var(--transition);
  position: relative;
}

.tab-btn:hover {
  color: var(--text-secondary);
  background: var(--bg-card-hover);
}

.tab-btn.active {
  color: var(--accent-green);
  background: rgba(108, 194, 74, 0.1);
}

.tab-panel {
  display: none;
  animation: fadeIn 0.4s ease;
}

.tab-panel.active {
  display: block;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

/* ============================================
   Platform Overview Diagram
   ============================================ */

.diagram-container {
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 40px 0;
}

.ecosystem-diagram {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 24px;
  max-width: 800px;
  width: 100%;
}

.ecosystem-center {
  background: linear-gradient(135deg, var(--primary-navy), var(--bg-card));
  border: 2px solid var(--accent-green);
  border-radius: var(--radius-lg);
  padding: 28px 48px;
  text-align: center;
  box-shadow: 0 0 30px rgba(108, 194, 74, 0.15);
}

.ecosystem-center h3 {
  font-size: 1.3rem;
  color: var(--accent-green);
}

.ecosystem-center p {
  font-size: 0.85rem;
  color: var(--text-secondary);
  margin-top: 4px;
}

.ecosystem-pillars {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
  width: 100%;
}

.ecosystem-pillar {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 28px 20px;
  text-align: center;
  transition: var(--transition);
  position: relative;
}

.ecosystem-pillar::before {
  content: '';
  position: absolute;
  top: -13px;
  left: 50%;
  transform: translateX(-50%);
  width: 2px;
  height: 12px;
  background: var(--accent-green);
}

.ecosystem-pillar:hover {
  border-color: var(--accent-teal);
  transform: translateY(-4px);
}

.ecosystem-pillar .icon {
  font-size: 2rem;
  color: var(--accent-teal);
  margin-bottom: 12px;
}

.ecosystem-pillar h4 {
  font-size: 1rem;
  margin-bottom: 8px;
}

.ecosystem-pillar p {
  font-size: 0.85rem;
  color: var(--text-secondary);
  line-height: 1.5;
}

/* ============================================
   Company Culture & Renewables
   ============================================ */

.culture-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 32px;
}

.culture-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 48px;
  transition: var(--transition);
}

.culture-card:hover {
  border-color: var(--accent-green);
}

.culture-card h3 {
  font-size: 1.5rem;
  margin-bottom: 16px;
}

.culture-card p {
  color: var(--text-secondary);
  margin-bottom: 24px;
  line-height: 1.7;
}

/* ============================================
   Platform Benefits
   ============================================ */

.benefits-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 24px;
}

.benefit-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 32px 24px;
  text-align: center;
  transition: var(--transition);
}

.benefit-card:hover {
  border-color: var(--accent-green);
  transform: translateY(-4px);
}

.benefit-icon {
  width: 56px;
  height: 56px;
  background: rgba(108, 194, 74, 0.1);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 16px;
  color: var(--accent-green);
  font-size: 1.5rem;
}

.benefit-card h4 {
  font-size: 1.05rem;
  margin-bottom: 8px;
}

.benefit-card p {
  font-size: 0.85rem;
  color: var(--text-secondary);
  line-height: 1.6;
}

/* ============================================
   Stats
   ============================================ */

.stats-row {
  display: flex;
  justify-content: center;
  gap: 48px;
  flex-wrap: wrap;
}

.stat-item {
  text-align: center;
}

.stat-circle {
  width: 160px;
  height: 160px;
  border-radius: 50%;
  background: conic-gradient(var(--accent-green) var(--progress, 0%), var(--bg-card) 0);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 16px;
  position: relative;
}

.stat-circle::before {
  content: '';
  position: absolute;
  width: 130px;
  height: 130px;
  border-radius: 50%;
  background: var(--bg-dark);
}

.stat-value {
  position: relative;
  z-index: 1;
  font-size: 2rem;
  font-weight: 800;
  color: var(--accent-green);
}

.stat-label {
  font-size: 0.9rem;
  color: var(--text-secondary);
  max-width: 180px;
  line-height: 1.5;
}

/* ============================================
   Implementation Timeline
   ============================================ */

.timeline {
  display: flex;
  flex-direction: column;
  gap: 24px;
  max-width: 800px;
  margin: 0 auto;
}

.timeline-item {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 28px 32px;
  transition: var(--transition);
}

.timeline-item:hover {
  border-color: var(--accent-teal);
}

.timeline-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 12px;
  flex-wrap: wrap;
  gap: 8px;
}

.timeline-header h4 {
  font-size: 1.1rem;
  color: var(--accent-teal);
}

.timeline-header span {
  font-size: 0.85rem;
  color: var(--text-muted);
  font-weight: 500;
}

.timeline-desc {
  font-size: 0.9rem;
  color: var(--text-secondary);
  margin-bottom: 16px;
}

.timeline-bar {
  height: 6px;
  background: var(--bg-dark);
  border-radius: 3px;
  overflow: hidden;
}

.timeline-bar-fill {
  height: 100%;
  background: linear-gradient(90deg, var(--accent-teal), var(--accent-green));
  border-radius: 3px;
  transition: width 1s ease;
}

/* ============================================
   Accordion
   ============================================ */

.accordion {
  max-width: 800px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.accordion-item {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  overflow: hidden;
  transition: var(--transition);
}

.accordion-item.active {
  border-color: var(--accent-green);
}

.accordion-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 20px 24px;
  cursor: pointer;
  transition: var(--transition);
}

.accordion-header:hover {
  background: var(--bg-card-hover);
}

.accordion-header h4 {
  font-size: 1.05rem;
  display: flex;
  align-items: center;
  gap: 12px;
}

.accordion-header h4 i {
  color: var(--accent-green);
  font-size: 1.2rem;
}

.accordion-toggle {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: var(--bg-dark);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-secondary);
  transition: var(--transition);
  flex-shrink: 0;
}

.accordion-item.active .accordion-toggle {
  transform: rotate(180deg);
  color: var(--accent-green);
}

.accordion-body {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.4s ease, padding 0.4s ease;
}

.accordion-item.active .accordion-body {
  max-height: 300px;
  padding: 0 24px 20px;
}

.accordion-body p {
  color: var(--text-secondary);
  font-size: 0.95rem;
  line-height: 1.7;
}

/* ============================================
   Data Lifecycle Diagram
   ============================================ */

.lifecycle-diagram {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0;
  max-width: 900px;
  margin: 0 auto;
}

.lifecycle-row {
  display: flex;
  justify-content: center;
  gap: 16px;
  flex-wrap: wrap;
}

.lifecycle-node {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 20px 28px;
  text-align: center;
  min-width: 160px;
  transition: var(--transition);
  position: relative;
}

.lifecycle-node:hover {
  border-color: var(--accent-teal);
  transform: scale(1.03);
}

.lifecycle-node .icon {
  font-size: 1.5rem;
  color: var(--accent-teal);
  margin-bottom: 8px;
}

.lifecycle-node h5 {
  font-size: 0.9rem;
  margin-bottom: 4px;
}

.lifecycle-node p {
  font-size: 0.75rem;
  color: var(--text-muted);
}

.lifecycle-arrow {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 8px 0;
  color: var(--accent-green);
  font-size: 1.2rem;
}

/* ============================================
   Testimonials
   ============================================ */

.testimonials-carousel {
  position: relative;
  max-width: 800px;
  margin: 0 auto;
  overflow: hidden;
}

.testimonials-track {
  display: flex;
  transition: transform 0.5s ease;
}

.testimonial-card {
  flex: 0 0 100%;
  padding: 0 12px;
}

.testimonial-inner {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 40px;
  text-align: center;
}

.testimonial-quote {
  font-size: 1.15rem;
  font-style: italic;
  color: var(--text-primary);
  line-height: 1.7;
  margin-bottom: 24px;
}

.testimonial-author {
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--accent-green);
}

.testimonial-dots {
  display: flex;
  justify-content: center;
  gap: 10px;
  margin-top: 28px;
}

.testimonial-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--border-color);
  border: none;
  cursor: pointer;
  transition: var(--transition);
}

.testimonial-dot.active {
  background: var(--accent-green);
  transform: scale(1.2);
}

/* ============================================
   Security Page
   ============================================ */

.security-hero {
  min-height: 50vh;
}

.security-features {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 24px;
}

.security-feature-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 32px;
  transition: var(--transition);
}

.security-feature-card:hover {
  border-color: var(--accent-green);
  transform: translateY(-4px);
}

.security-feature-card .icon {
  width: 48px;
  height: 48px;
  background: rgba(108, 194, 74, 0.1);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 16px;
